    s=f.read()
# Simple patch: add extra guards after line with if ((input == NULL) || (input->cur == NULL)) return;
search = '    if ((input == NULL) || (input->cur == NULL))\n        return;'
if search in s:
    s = s.replace(search, '    if ((input == NULL) || (input->cur == NULL))\n        return;\n\n    /* Additional guards to avoid use-after-free in error reporting */\n    if ((input->base == NULL) || (input->end == NULL))\n        return;')
else:
