# Patch loop inside: add cur >= input->end check inside the copy loop
s = s.replace('while ((*cur != 0) && (*(cur) != \n) && (*(cur) != '\r')) {', 'while ((*cur != 0) && (*(cur) != \'\n\') && (*(cur) != \'\r\')) {')
# We'll insert check right after the while header content is replaced; safer to do targeted insert by locating the block
old_block = '''    /* copy selected text to our buffer */
    while ((*cur != 0) && (*(cur) != '\n') && (*(cur) != '\r')) {
        int len = input->end - cur;
        int c = xmlGetUTF8Char(cur, &len);

        if ((c < 0) || (n + len > sizeof(content)-1))
            break;
        cur += len;
        n += len;
    }'''
new_block = '''    /* copy selected text to our buffer */
    while ((*cur != 0) && (*(cur) != '\n') && (*(cur) != '\r')) {
        if (cur >= input->end) {
            break;
        }
        int len = input->end - cur;
        int c = xmlGetUTF8Char(cur, &len);

        if ((c < 0) || (n + len > sizeof(content)-1))
            break;
        cur += len;
        n += len;
    }'''
if old_block in s:
    s = s.replace(old_block, new_block)
